"""Rasa-owned models for the information retrieval layer.

These models replace the LangChain primitives that Rasa previously relied on
(`langchain_core.documents.Document`) as part of the LangChain decoupling
effort (ENG-2876).
"""

from __future__ import annotations

import warnings
from typing import Any, Dict

from pydantic import BaseModel, Field


class Document(BaseModel):
    """A single retrievable document.

    Rasa-owned replacement for ``langchain_core.documents.Document``. The
    document body is stored under ``text`` (LangChain used ``page_content``).
    """

    text: str
    metadata: Dict[str, Any] = Field(default_factory=dict)

    @property
    def page_content(self) -> str:
        """Deprecated read-only alias for :attr:`text`.

        Kept for one release to ease migration for custom
        ``InformationRetrieval`` stores that still read ``page_content`` from
        Rasa return types. Prefer :attr:`text`.
        """
        warnings.warn(
            "`Document.page_content` is deprecated and will be removed in a "
            "future release. Use `Document.text` instead.",
            DeprecationWarning,
            stacklevel=2,
        )
        return self.text
